// Single-cycle FSM to control the ringer and motor.
module TopModule(
  input  ring,
  input  vibrate_mode,
  output reg ringer,
  output reg motor
);
  reg [1:0] state;
  always @(*) begin
    case (state)
      2'b00: begin // Ringer off, motor off.
        ringer = 1'b0;
        motor = 1'b0;
        if (ring) state = 2'b01;
      end
      2'b01: begin // Ringer on, motor off.
        ringer = 1'b1;
        motor = 1'b0;
        if (vibrate_mode) state = 2'b11;
        else if (!ring) state = 2'b00;
      end
      2'b11: begin // Ringer off, motor on.
        ringer = 1'b0;
        motor = 1'b1;
        if (!vibrate_mode) state = 2'b01;
      end
      default: state = 2'b00;
    endcase
  end
endmodule

